// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address sender, address target, bool emergency) public {
        // Ensure sender is not the DAO (we are the DAO in setUp) and not already governed
        vm.assume(sender != address(this) && !c.governed(sender));

        // Set up the contract so that sender becomes governed
        address[] memory govList = new address[](1);
        bool[] memory isGov = new bool[](1);
        govList[0] = sender;
        isGov[0] = true;

        // We need to call setGoverned via onlySuccessfulProposal modifier
        // The modifier checks that configured is false OR the sender is a successful proposal
        // In setUp, configured is false (default), so we can call directly
        vm.prank(address(this)); // DAO
        c.setGoverned(govList, isGov);

        // Now sender is governed; store the expected governed status after call
        bool expectedGoverned = true;

        // Call assertGovernanceApproved as the governed sender
        vm.prank(sender);
        // This might revert; we just care about the state after the call
        (bool success, ) = address(c).call(
            abi.encodeWithSignature("assertGovernanceApproved(address,address,bool)", sender, target, emergency)
        );

        // The rule: after any call (even reverting), the sender's governed status must not change
        assertTrue(c.governed(sender) == expectedGoverned, "Governed status changed");
    }
}

